-- Dados iniciais. Rode depois de schema.sql (SQL Editor > New query > colar > Run).
-- Pode rodar de novo: não duplica nem apaga o que você já escreveu.

-- Calendário de 24 semanas (72 episódios)
on conflict (semana, dia) do nothing;

-- Primeiro conteúdo gratuito: o ebook dos papers (arquivo já está no site)
select 'Os papers que mudaram o seu dinheiro',
       'Dez artigos acadêmicos que transformaram a forma como o mundo investe, explicados em uma página cada. Sem fórmulas, com exemplos do dia a dia.',
       'ebook',
       'conteudos/os-papers-que-mudaram-o-seu-dinheiro.pdf',
       'assets/img/capa-papers.png',
       'terracota', true, true, 0
where not exists (select 1 from public.conteudos where arquivo_url = 'conteudos/os-papers-que-mudaram-o-seu-dinheiro.pdf');
